package com.wiseway.service;
import com.wiseway.api.ApiDtos.*; import com.wiseway.persistence.*; import com.wiseway.web.NotFoundException; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import java.math.*; import java.time.*; import java.util.*; import java.util.stream.*;
@Service public class ExpenseService { private final JourneyLogRepository repo; public ExpenseService(JourneyLogRepository r){repo=r;} public List<ExpenseResponse> list(LocalDate from,LocalDate to){var rows=(from!=null&&to!=null)?repo.findByTravelDateBetweenOrderByTravelDateDesc(from,to):repo.findAll();return rows.stream().map(this::out).toList();} @Transactional public ExpenseResponse create(ExpenseRequest r){return out(repo.save(new JourneyLogEntity(r.travelDate(),r.origin().trim(),r.destination().trim(),r.mode(),r.actualAmount(),r.currency()==null?"INR":r.currency(),r.notes())));} @Transactional public void delete(Long id){if(!repo.existsById(id))throw new NotFoundException("Journey log not found.");repo.deleteById(id);} public Summary summary(LocalDate from,LocalDate to,String groupBy){if(from==null||to==null||from.isAfter(to))throw new IllegalArgumentException("Start date must be on or before end date.");var rows=repo.findByTravelDateBetweenOrderByTravelDateDesc(from,to);var total=rows.stream().map(JourneyLogEntity::getActualAmount).reduce(BigDecimal.ZERO,BigDecimal::add);var groups=rows.stream().collect(Collectors.groupingBy(e->"MODE".equals(groupBy)?e.getMode().name():e.getTravelDate().toString(),LinkedHashMap::new,Collectors.toList())).entrySet().stream().map(e->new Group(e.getKey(),e.getValue().stream().map(JourneyLogEntity::getActualAmount).reduce(BigDecimal.ZERO,BigDecimal::add),e.getValue().size())).toList();return new Summary(from,to,"INR",total,rows.size(),groups);} private ExpenseResponse out(JourneyLogEntity e){return new ExpenseResponse(e.getId(),e.getTravelDate(),e.getOrigin(),e.getDestination(),e.getMode(),e.getActualAmount(),e.getCurrency(),e.getNotes(),e.getCreatedAt());}}
